events.css:
body {
    font-family: Georgia, serif;
    font-size: 18px;
    line-height: 1.5;
    color: #556B2F;
    background-color: #F5DEB3;
    margin: 0;
    padding: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

@media (prefers-color-scheme: dark) {
    body {
        color: #F5DEB3;
        background-color: #556B2F;
    }
}

.hero {
    position: relative;
    width: 100%;
    height: 80vh;
    min-height: 300px;
    margin-bottom: 2rem;
}

.hero-picture {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    z-index: -1;
}

.hero-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    color: #F5DEB3;
    background-color: rgba(85, 107, 47, 0.7);
    padding: 2rem;
    border-radius: 0.5rem;
}

.name {
    font-size: 4rem;
    margin: 0;
}

.tagline {
    font-size: 1.5rem;
    margin: 0;
}

.site-nav {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 1rem;
    padding: 1rem;
    background-color: #D2B48C;
    margin-bottom: 2rem;
}

.site-nav a {
    color: #556B2F;
    text-decoration: none;
    padding: 0.5rem 1rem;
    border-radius: 0.25rem;
}

.site-nav a:hover {
    background-color: #8B4513;
    color: #F5DEB3;
}

main {
    flex: 1;
    padding: 0 1rem;
    max-width: 1200px;
    margin: 0 auto;
    width: 100%;
}

.sec {
    margin-bottom: 2rem;
    padding: 1rem;
    background-color: rgba(210, 180, 140, 0.7);
    border-radius: 0.5rem;
}

.sec h2 {
    font-size: 2rem;
    margin-top: 0;
    color: #8B4513;
}

.photos {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 1rem;
    margin-bottom: 2rem;
}

.photo {
    position: relative;
    overflow: hidden;
    border-radius: 0.5rem;
}

.photo img {
    width: 100%;
    height: auto;
    display: block;
}

.photo figcaption {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    background-color: rgba(85, 107, 47, 0.7);
    color: #F5DEB3;
    padding: 1rem;
    margin: 0;
}

.facts {
    margin-bottom: 2rem;
    padding: 1rem;
    background-color: rgba(210, 180, 140, 0.7);
    border-radius: 0.5rem;
}

.facts h2 {
    font-size: 2rem;
    margin-top: 0;
    color: #8B4513;
}

dl {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 0.5rem;
}

dt {
    font-weight: bold;
}

.foot {
    text-align: center;
    padding: 1rem;
    background-color: #D2B48C;
    color: #556B2F;
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
